    .callout-warning { border-color: #d97706; background: #fffbeb; }
    .callout-success { border-color: #166534; background: #f0fdf4; }
    .callout strong { display: block; margin-bottom: 4px; font-size: 13px; letter-spacing: 0.3px; }

    /* ── Takeaway block ── */
    .takeaway {
      display: flex;
