    .rec-card p  { font-size: 14px; color: var(--muted); }

    /* ── Bar chart wrapper ── */
    .chart-box { position: relative; }

    /* ── Star rating visual ── */
    .star-bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; font-size: 13px; }
